import{_ as n,l as s,o as t,c as d,v as i,p,x as l,d as r,i as m,S as h,b as e}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"增量规则与关联记忆","description":"","frontmatter":{"title":"增量规则与关联记忆","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/delta-rule-memory.md","filePath":"llm/delta-rule-memory.md","lastUpdated":1789023840000}'),_={name:"llm/delta-rule-memory.md"};function c(u,a,S,k,f,b){const o=s("Mermaid");return t(),d("div",null,[a[1]||(a[1]=i('<h1 id="增量规则与关联记忆" tabindex="-1">增量规则与关联记忆 <a class="header-anchor" href="#增量规则与关联记忆" aria-label="Permalink to &quot;增量规则与关联记忆&quot;">​</a></h1><div class="epigraph"><p>线性注意力的状态更新若改成 delta 规则，写入新键值时会擦除该键旧有的关联，状态更像一张可改写的表。</p><footer>—— Schlag, Irie &amp; Schmidhuber, Linear Transformers Are Secretly Fast Weight Programmers, ICML 2021；并行 delta 规则见 Yang et al., 2024</footer></div><p><a href="/llm/hgrn">上一课</a>的更新是对新输入做凸组合，旧状态按门缩小，没有「这个键以前写过什么」的寻址擦除。<a href="/llm/gated-linear-attention">GLA</a> 的 \\(S\\leftarrow G\\odot S+kv^\\top\\) 同样是加性写入。本课补 delta 规则：用当前键去读旧状态，把冲突分量减掉再写。这是快权重 / 关联记忆路线。下一课 TTT 把整段更新看成测试时的一步梯度，是同一想法的优化表述。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加性外积遇到重复键会叠两层值，读出来是糊的。Softmax 注意力每次都拿完整 KV 表，天然以最新或分数最高者为准。线性状态若想模拟「变量赋值」，需要：<strong>写入键 \\(k\\) 时，先去掉 \\(S\\) 里与 \\(k\\) 相关的旧行</strong>。缺口就是这条 delta / 误差修正更新，而不是再加一个遗忘门。</p><p>Schlag 等人指出线性 Transformer 等价于快权重编程器，delta 规则是其中更像记忆改写的一种。Yang 等人给出沿长度并行化的算法，使它能进现代训练核。</p><p><span class="marginnote">这里的「键」是内容向量，不是注意力课里必须经过 softmax 的那张表。状态仍是固定大小矩阵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一种常见形式：</p> \\[S_t=S_{t-1}-\\beta_t(S_{t-1}k_t)k_t^\\top+\\beta_t v_t k_t^\\top, \\]<p>即在 \\(k_t\\) 方向上把旧读出 \\(S_{t-1}k_t\\) 换成 \\(v_t\\)，\\(\\beta_t\\in(0,1]\\) 为写入强度。\\(\\beta=1\\) 且 \\(k\\) 单位化时，近似投影到与 \\(k\\) 正交补再写入，旧关联被擦。读出仍 \\(o_t=S_t q_t\\)。</p><p>\\(\\beta_t\\)、以及是否对 \\(k\\) 归一化，决定稳定性。未归一化时反复写同一方向会数值炸掉。并行化要把这种 rank-1 更新收进结合结构，比对角门更绕，需要专门分块（Yang 等人的工作），不能假设 GLA 核直接能跑 delta。</p><h3 id="与加性线性注意力" tabindex="-1">与加性线性注意力 <a class="header-anchor" href="#与加性线性注意力" aria-label="Permalink to &quot;与加性线性注意力&quot;">​</a></h3><p>加性：\\(S+=kv^\\top\\)，适合累积证据。Delta：适合覆写。语言模型两者都需要——计数、求和要累积，变量绑定要覆写。混合层或混合头可以分摊，本课只把覆写算子钉死。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把 \\(S\\) 看成线性映射「键 \\(\\mapsto\\) 值」。Delta 是对这张映射做一步校正，目标是 \\(Sk\\approx v\\)。多次不同键的校正叠在同一 \\(S\\) 上，键不正交就会互相干扰——容量仍是矩阵的秩与条件数，不是无限槽位。正交性越好，越像一张表；随机高维键近似正交，这是为何 \\(d_k\\) 不能太小，连回<a href="/llm/head-dim-vs-heads">头维</a>。</p><p>精确单点召回取决于键是否撞车以及 \\(\\beta\\) 是否把旧值擦干净。这比纯加性强，仍弱于保存全表的 softmax。</p><p><span class="marginnote">Fast weight programmer 的说法：慢权重是 \\(W_q,W_k,W_v\\)，快权重是 \\(S_t\\)，每个 token 改写快权重。TTT 会把「改写」说成「对快权重做梯度步」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>并行核不通用，缺实现则训练退回逐步，不可用。键碰撞时 delta 会误擦。\\(\\beta\\) 学崩会要么不写要么每步清空。不要把 delta 规则宣传成「线性复杂度的精确 KV」——表的槽数仍由状态秩决定。下一课把校正步写成显式的测试时损失下降，解释会更干净，算法可以仍是本课这种 rank-1 更新。</p>',20)),(t(),p(h,null,{default:l(()=>[m(o,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22S_%7Bt-1%7D%22%5D%20--%3E%20Read%5B%22%E8%AF%BB%E5%87%BA%20S%20k%22%5D%0A%20%20K%5B%22k_t%22%5D%20--%3E%20Read%0A%20%20Read%20--%3E%20Erase%5B%22%E6%B2%BF%20k%20%E6%93%A6%E9%99%A4%E6%97%A7%E5%80%BC%22%5D%0A%20%20V%5B%22v_t%22%5D%20--%3E%20Write%5B%22%E5%86%99%E5%85%A5%E6%96%B0%E5%85%B3%E8%81%94%22%5D%0A%20%20Erase%20--%3E%20S2%5B%22S_t%22%5D%0A%20%20Write%20--%3E%20S2%0A%20%20Q%5B%22q_t%22%5D%20--%3E%20Out%5B%22S_t%20q%22%5D%0A%20%20S2%20--%3E%20Out%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"Delta 规则在写入时擦除同键旧关联，让线性状态更像可改写的映射，而不是纯累加。"),e("li",null,"容量仍受状态秩与键正交性限制，不是无损 KV 表。"),e("li",null,"并行训练需要专门分块，不能假定 GLA 核兼容。"),e("li",null,"累积证据与覆写变量是两种需求，不要只用一种更新。"),e("li",null,"出处：Schlag et al., ICML 2021；Yang et al., 2024。")],-1))])}const B=n(_,[["render",c]]);export{A as __pageData,B as default};
